+  border-radius:22px;
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(0,0,0,.44));
+  box-shadow:0 28px 80px rgba(0,0,0,.65);
+  padding:24px;
+}
