+.auth-card p{margin:0 0 18px; color:rgba(255,255,255,.70); line-height:1.6;}
+.form-stack{display:grid; gap:12px;}
+.label{font-size:13px; color:rgba(255,255,255,.72); font-weight:700; letter-spacing:.02em;}
+.input-rect{
+  width:100%;
+  border-radius:16px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(0,0,0,.50);
+  color:var(--text);
+  padding:14px 14px;
+  font-size:16px;
+  font-weight:600;
+  min-height:48px;
+}
+.input-rect:focus{outline:none; border-color:rgba(229,9,20,.55); box-shadow:0 0 0 4px rgba(229,9,20,.16);}
+.error{display:none; color:#fecaca; font-weight:700; font-size:13px;}
+.error[data-show="true"]{display:block;}
+
+.help{
+  margin-top:14px;
+  border-radius:16px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.04);
+}
+.help-btn{
+  width:100%;
+  border:none;
+  background:transparent;
+  color:rgba(255,255,255,.86);
+  padding:14px 14px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  cursor:pointer;
+  min-height:48px;
+  font-weight:850;
+}
+.help-panel{
+  max-height:0;
+  overflow:hidden;
+  transition:max-height 280ms var(--ease);
+}
+.help[data-open="true"] .help-panel{max-height:220px;}
+.help-panel-inner{padding:0 14px 14px; color:rgba(255,255,255,.70); line-height:1.7;}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr;}
+  .mosaic{inset:-90px; transform:rotate(-8deg) scale(1.06);}
+  .mosaic-grid{grid-template-columns:repeat(6, 1fr); gap:12px;}
+  .h1{font-size:46px;}
+  .carousel-controls{top:-50px;}
+  .grid-4{grid-template-columns:repeat(2, 1fr);}
+  .footer-grid{grid-template-columns:repeat(2, 1fr);}
+}
+@media (max-width: 520px){
+  .container{padding:0 16px;}
+  .header-inner{padding:14px 0;}
+  .select{display:none;}
+  .h1{font-size:38px;}
+  .subhead{font-size:16px;}
+  .hero{padding:54px 0 54px;}
+  .grid-4{grid-template-columns:1fr;}
+  .rank-card{width:176px;}
+  .rank-art{height:240px;}
+  .rank-num{font-size:82px;}
+  .auth-card{padding:18px;}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important; transition:none !important;}
+}
+
*** End Patch
